1	// SPDX-License-Identifier: Apache-2.0
2	//! Asserts every metric family referenced in the committed Grafana dashboards + Prometheus
3	//! alert rules is a registered family (after suffix-normalisation) — so ops artifacts can't
4	//! reference a metric we don't emit. `promtool` covers PromQL *validity*; this covers *name
5	//! drift*.
6	//!
7	//! Extraction is prefix-anchored rather than a blanket identifier scan: a PromQL `expr` mixes
8	//! metric names with label keys (`status_class`, `grpc_status`, `decision`, ...), function names
9	//! (`rate`, `sum`, `histogram_quantile`, `by`, `le`, ...), and template vars
10	//! (`$__rate_interval`). Every real metric in this repo is prefixed `iam_` or `gateway_`, so a
11	//! token only counts as a metric-name reference when it matches `^(iam|gateway)_[a-z0-9_]+$` —
12	//! that automatically excludes all of the above without needing a label/function blocklist.
13	
14	use paigasus_observability::names::ALL;
15	
16	/// Strip a trailing histogram/summary suffix so `foo_seconds_bucket` matches the registered
17	/// family `foo_seconds` (Prometheus expands a histogram into `_bucket`/`_sum`/`_count` series).
18	fn normalize(id: &str) -> &str {
19	    for suffix in ["_bucket", "_sum", "_count"] {
20	        if let Some(base) = id.strip_suffix(suffix) {
21	            return base;
22	        }
23	    }
24	    id
25	}
26	
27	fn is_known(id: &str) -> bool {
28	    let normalized = normalize(id);
29	    ALL.contains(&normalized) || ALL.contains(&id)
30	}
31	
32	/// Extract every `iam_`/`gateway_`-prefixed token from a PromQL expression. Tokenizing by
33	/// splitting on any char outside `[a-z0-9_]` and filtering to the two real metric prefixes
34	/// discards label keys, function names, and template vars (`$__rate_interval` splits into
35	/// `__rate_interval`, which fails the prefix check) without needing to enumerate them.
36	fn metric_idents(expr: &str) -> Vec<String> {
37	    expr.split(|c: char| !(c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_'))
38	        .filter(|token| !token.is_empty() && (token.starts_with("iam_") || token.starts_with("gateway_")))
39	        .map(str::to_owned)
40	        .collect()
41	}
42	
43	/// Walk a Grafana dashboard JSON doc and collect every `targets[].expr` string, recursing into
44	/// `panels[].panels[]` (Grafana nests panels inside "row" panels).
45	fn collect_exprs_from_dashboard(json: &serde_json::Value) -> Vec<String> {
46	    let mut exprs = Vec::new();
47	    if let Some(panels) = json.get("panels").and_then(serde_json::Value::as_array) {
48	        collect_panel_exprs(panels, &mut exprs);
49	    }
50	    exprs
51	}
52	
53	fn collect_panel_exprs(panels: &[serde_json::Value], exprs: &mut Vec<String>) {
54	    for panel in panels {
55	        if let Some(targets) = panel.get("targets").and_then(serde_json::Value::as_array) {
56	            for target in targets {
57	                if let Some(expr) = target.get("expr").and_then(serde_json::Value::as_str) {
58	                    exprs.push(expr.to_owned());
59	                }
60	            }
61	        }
62	        if let Some(nested) = panel.get("panels").and_then(serde_json::Value::as_array) {
63	            collect_panel_exprs(nested, exprs);
64	        }
65	    }
66	}
67	
68	/// Walk a Prometheus alert-rules YAML doc and collect every `groups[].rules[].expr` string.
69	fn collect_exprs_from_rules(doc: &serde_norway::Value) -> Vec<String> {
70	    let mut exprs = Vec::new();
71	    if let Some(groups) = doc.get("groups").and_then(serde_norway::Value::as_sequence) {
72	        for group in groups {
73	            if let Some(rules) = group.get("rules").and_then(serde_norway::Value::as_sequence) {
74	                for rule in rules {
75	                    if let Some(expr) = rule.get("expr").and_then(serde_norway::Value::as_str) {
76	                        exprs.push(expr.to_owned());
77	                    }
78	                }
79	            }
80	        }
81	    }
82	    exprs
83	}
